가로 = int(input("가로: "))
세로 = int(input("세로: "))
for 줄 in range(세로):
    for 칸 in range(가로):
        print("#", end="")
    print()

크기 = int(input("크기: "))
끝 = 크기 - 1
for 줄 in range(크기):
    for 칸 in range(크기):
        if 줄 == 0 or 줄 == 끝 or 칸 == 0 or 칸 == 끝:
            print("*", end="")
        else:
            print(" ", end="")
    print()

합 = int(input("합: "))
개수 = 0
for a in range(1, 7):
    for b in range(1, 7):
        for c in range(1, 7):
            if a + b + c == 합:
                개수 += 1
print(개수, "가지")
